    r"\b(?:и\s+вс[её]|на\s+этом\s+вс[её])\b|"
    rf"\bитого\s*:?\s*{_ATTACHMENT_COUNT}\b|"
    rf"\b(?:всего|количеств\w*)\s*[:—-]\s*{_ATTACHMENT_COUNT}\b|"
