# Verification verdict states. `skipped` means verification was deliberately not
# run (disabled, LLM off, or answer too short) and must never be conflated with a
# passed check; `unknown` means verification was attempted but could not produce a
# trustworthy verdict — both `unknown` and `failed` warn the user.
VERDICT_PASSED = "passed"
VERDICT_FAILED = "failed"
VERDICT_UNKNOWN = "unknown"
VERDICT_SKIPPED = "skipped"


def _matched_region(hit: dict[str, Any]) -> str:
    """The text a query-aware excerpt should be taken from.

    Normally the whole body. When dense recall won on one passage, retrieval attaches
    that passage's character span, and excerpting inside it keeps the evidence shown
    to the model and the verifier aligned with the reason the object was retrieved.
    """
    body = str(hit.get("content") or hit.get("summary") or "")
    span = hit.get("_embedding_chunk_span")
    if isinstance(span, (list, tuple)) and len(span) == 2:
        try:
            start, end = int(span[0]), int(span[1])
        except (TypeError, ValueError):
            return body
        content = str(hit.get("content") or "")
        if 0 <= start < end <= len(content):
            return content[start:end]
    return body


_AGENT_GRAPH_PATHS_MAX_CHARS = 8_000
_AGENT_GRAPH_COUNT_CAP = 1_000_000_000


def _graph_count(value: Any, *, minimum: int = 0) -> int:
    try:
        parsed = int(value)
    except (OverflowError, TypeError, ValueError):
        return minimum
    return max(minimum, min(max(0, parsed), _AGENT_GRAPH_COUNT_CAP))


def _graph_text_for_prompt(value: Any, *, limit: int) -> str:
    return value[:limit] if isinstance(value, str) else ""


def _graph_endpoint_id_for_prompt(value: Any) -> str:
    if isinstance(value, dict):
        value = value.get("id")
    return _graph_text_for_prompt(value, limit=120)


def _graph_endpoint_for_prompt(
    value: Any,
    entity_lookup: dict[str, dict[str, Any]] | None = None,
) -> str | dict[str, str]:
    """Keep an endpoint identifiable without forwarding an entity's raw metadata."""

    if isinstance(value, dict):
        endpoint: dict[str, str] = {}
        for key, limit in (("id", 120), ("name", 200), ("entity_type", 80)):
            item = value.get(key)
            if isinstance(item, str):
                endpoint[key] = item[:limit]
        return endpoint
    entity_id = _graph_text_for_prompt(value, limit=120)
    known = (entity_lookup or {}).get(entity_id)
    if known:
        endpoint = {"id": entity_id}
        for key, limit in (("name", 200), ("entity_type", 80)):
            item = known.get(key)
            if isinstance(item, str):
                endpoint[key] = item[:limit]
        return endpoint
    return entity_id


def _graph_number(value: Any) -> float | None:
    """A JSON-safe finite graph score/weight, or no value for legacy garbage."""

    try:
        number = float(value)
    except (OverflowError, TypeError, ValueError):
        return None
    # NaN and infinities would make the JSON envelope non-portable.  This comparison
    # rejects all three without another dependency.
    if not -1e308 <= number <= 1e308:
        return None
    return round(number, 6)


_TOOL_HISTORY_FIELDS = (
    "known_at",
    "known_at_floor",
    "history_complete",
    "identity_basis",
    "temporal_basis",
)
_SAFE_GRAPH_TOOL_PAYLOAD_MAX_CHARS = 10_500
_SAFE_MEMORY_RESULTS = 8
_SAFE_ENTITY_RELATIONS = 12
_SAFE_ENTITY_KNOWLEDGE = 8
_CURRENT_GRAPH_TOOL_BOUNDARY = object()


def _tool_request_boundaries(tool_name: str, arguments: Any) -> tuple[str, str]:
    """Normalize explicit tool axes; present non-strings never mean "omitted"."""

    if arguments is None:
        arguments = {}
    if not isinstance(arguments, Mapping):
        raise ValueError("tool arguments are not a mapping")
    normalized: dict[str, str] = {"as_of": "", "known_at": ""}
    for key in ("as_of", "known_at"):
        if key not in arguments:
            continue
        value = arguments[key]
        if not isinstance(value, str):
            raise ValueError(f"requested {key} must be a string")
        cleaned = value.strip()
        if not cleaned:
            continue
        if key == "known_at":
            normalized[key] = normalize_known_at(cleaned)
        elif tool_name == "memory_search":
            parsed = iso_date(cleaned)
            if parsed is None:
                raise ValueError("requested as_of is invalid for memory_search")
            normalized[key] = parsed
        else:
            normalized[key] = normalize_event_date(cleaned)[0]
    return normalized["as_of"], normalized["known_at"]


def _tool_temporal_contract(
    raw: Any,
    *,
    requested_as_of: str,
    requested_known_at: str,
    label: str,
) -> tuple[str, str, str, bool, str, str] | None:
    """Validate one self-contained tool boundary without borrowing sibling fields."""

    if not isinstance(raw, Mapping):
        raise ValueError(f"{label} is not a mapping")
    if (requested_as_of or requested_known_at) and ("as_of" not in raw or "known_at" not in raw):
        raise ValueError(f"{label} must echo both temporal axes")
    raw_as_of = raw.get("as_of", "")
    raw_known_at = raw.get("known_at", "")
    if not isinstance(raw_as_of, str):
        raise ValueError(f"{label} returned a non-string as_of")
    if not isinstance(raw_known_at, str):
        raise ValueError(f"{label} returned a non-string known_at")
    as_of = raw_as_of.strip()
    known_at = raw_known_at.strip()
    if as_of:
        try:
            normalized_as_of = normalize_event_date(as_of)[0]
        except ValueError as exc:
            raise ValueError(f"{label} returned an invalid as_of") from exc
        if normalized_as_of != as_of:
            raise ValueError(f"{label} returned a non-normalized as_of")
    if known_at and normalize_known_at(known_at) != known_at:
        raise ValueError(f"{label} returned a non-normalized known_at")
    if requested_as_of or requested_known_at:
        if as_of != requested_as_of:
            raise ValueError(f"{label} returned a different requested as_of boundary")
        if known_at != requested_known_at:
            raise ValueError(f"{label} returned a different requested known_at boundary")
    if not (as_of or known_at or requested_as_of or requested_known_at):
        return None
    if known_at:
        for key in _TOOL_HISTORY_FIELDS:
            if key not in raw:
                raise ValueError(f"{label} is missing {key}")
        floor = raw.get("known_at_floor")
        if (
            not isinstance(floor, str)
            or not floor
            or normalize_known_at(floor, reject_future=False) != floor
            or floor > known_at
        ):
            raise ValueError(f"{label} returned an invalid relation-history floor")
        if raw.get("history_complete") is not True:
            raise ValueError(f"{label} returned an incomplete relation-history snapshot")
        if raw.get("identity_basis") != "current_names" or raw.get("temporal_basis") != "bitemporal":
            raise ValueError(f"{label} returned an unsupported graph snapshot basis")
        return known_at, as_of, floor, True, "current_names", "bitemporal"
    if raw.get("temporal_basis") != "valid_time":
        raise ValueError(f"{label} returned an unsupported valid-time basis")
    return "", as_of, "", False, "", "valid_time"


def _historical_tool_graph_context(
    tool_name: str,
    data: Any,
    arguments: Any = None,
) -> dict[str, Any] | None:
    """Adopt one independently complete valid-time or bitemporal tool snapshot."""

    if tool_name not in {"memory_search", "entity_lookup"}:
        return None
    requested_as_of, requested_known_at = _tool_request_boundaries(tool_name, arguments)
    if not isinstance(data, Mapping):
        if requested_as_of or requested_known_at:
            raise ValueError(f"{tool_name} result is not a mapping")
        return None

    if tool_name == "memory_search":
        raw_snapshot = data.get("graph_context")
        envelope_is_temporal = bool(data.get("as_of") or data.get("known_at"))
        snapshot_is_temporal = bool(
            isinstance(raw_snapshot, Mapping) and (raw_snapshot.get("as_of") or raw_snapshot.get("known_at"))
        )
        if not (requested_as_of or requested_known_at) and (envelope_is_temporal or snapshot_is_temporal):
            raise ValueError("memory_search returned an unrequested temporal boundary")
        if not (requested_as_of or requested_known_at or envelope_is_temporal or snapshot_is_temporal):
            return None
        envelope_contract = _tool_temporal_contract(
            data,
            requested_as_of=requested_as_of,
            requested_known_at=requested_known_at,
            label="memory_search envelope",
        )
        snapshot_contract = _tool_temporal_contract(
            raw_snapshot,
            requested_as_of=requested_as_of,
            requested_known_at=requested_known_at,
            label="memory_search graph_context",
        )
        if envelope_contract is None or snapshot_contract is None:
            raise ValueError("memory_search dropped a temporal contract")
        if envelope_contract != snapshot_contract:
            raise ValueError("memory_search envelope and graph_context disagree")
        contract = envelope_contract
        assert isinstance(raw_snapshot, Mapping)
        adopted = _memory_graph_context_for_llm(
            raw_snapshot,
            query=_graph_text_for_prompt(
                raw_snapshot.get("query") or data.get("query"),
                limit=700,
            ),
            as_of=contract[1],
            known_at=contract[0],
        )
    else:
        if not (requested_as_of or requested_known_at) and (data.get("as_of") or data.get("known_at")):
            raise ValueError("entity_lookup returned an unrequested temporal boundary")
        entity_contract = _tool_temporal_contract(
            data,
            requested_as_of=requested_as_of,
            requested_known_at=requested_known_at,
            label="entity_lookup payload",
        )
        if entity_contract is None:
            return None
        contract = entity_contract
        adopted = {
            "query": "",
            "expanded": True,
            "paths": [],
            "paths_matched_at_least": 0,
            "paths_truncated": False,
        }

    known_at, as_of, floor, history_complete, identity_basis, temporal_basis = contract
    adopted.update(
        {
            "as_of": as_of,
            "known_at": known_at,
            "temporal_basis": temporal_basis,
        }
    )
    if known_at:
        adopted.update(
            {
                "known_at_floor": floor,
                "history_complete": history_complete,
                "identity_basis": identity_basis,
            }
        )
    return adopted


def _safe_memory_result(raw: Any) -> dict[str, Any]:
    if not isinstance(raw, Mapping):
        return {}
    result: dict[str, Any] = {}
    for key, limit in (
        ("id", 160),
        ("title", 240),
        ("kind", 80),
        ("updated_at", 40),
        ("excerpt", 520),
    ):
        value = _graph_text_for_prompt(raw.get(key), limit=limit)
        if value:
            result[key] = value
    return result


def _safe_entity_relation(raw: Any) -> dict[str, str]:
    if not isinstance(raw, Mapping):
        return {}
    relation_type = raw.get("type") if isinstance(raw.get("type"), str) else raw.get("relation_type")
    source = raw.get("source") if isinstance(raw.get("source"), str) else raw.get("source_name")
    target = raw.get("target") if isinstance(raw.get("target"), str) else raw.get("target_name")
    return {
        "type": _graph_text_for_prompt(relation_type, limit=80),
        "source": _graph_text_for_prompt(source, limit=200),
        "target": _graph_text_for_prompt(target, limit=200),
        "valid_from": _graph_text_for_prompt(raw.get("valid_from"), limit=32),
        "valid_to": _graph_text_for_prompt(raw.get("valid_to"), limit=32),
    }


def _safe_graph_tool_payload(
    tool_name: str,
    data: Any,
    adopted: dict[str, Any] | None,
) -> dict[str, Any]:
    """Allowlist graph-reading tool data before any LLM/evidence serialization."""

    if not isinstance(data, Mapping):
        raise ValueError(f"{tool_name} result is not a mapping")
    safe: dict[str, Any] = {}
    if tool_name == "memory_search":
        for key in ("count", "matched_at_least", "shown", "filtered_out"):
            if key in data:
                safe[key] = _graph_count(data.get(key))
        for key, limit in (
            ("query", 700),
            ("empty_because", 80),
            ("detail", 400),
            ("as_of", 32),
            ("known_at", 40),
            ("known_at_floor", 40),
            ("identity_basis", 40),
            ("temporal_basis", 40),
        ):
            if key in data:
                safe[key] = _graph_text_for_prompt(data.get(key), limit=limit)
        if "history_complete" in data:
            safe["history_complete"] = data.get("history_complete") is True
        raw_results = data.get("results")
        results = (
            [_safe_memory_result(item) for item in raw_results[:_SAFE_MEMORY_RESULTS]]
            if isinstance(raw_results, list)
            else []
        )
        safe["results"] = [item for item in results if item]
        if isinstance(raw_results, list) and len(raw_results) > len(safe["results"]):
            safe["results_shown"] = len(safe["results"])
            safe["results_truncated"] = True
        raw_graph = data.get("graph_context")
        if isinstance(raw_graph, Mapping):
            safe["graph_context"] = adopted or _memory_graph_context_for_llm(
                raw_graph,
                query=_graph_text_for_prompt(raw_graph.get("query") or data.get("query"), limit=700),
                as_of=_graph_text_for_prompt(raw_graph.get("as_of") or data.get("as_of"), limit=32),
                known_at=_graph_text_for_prompt(
                    raw_graph.get("known_at") or data.get("known_at"),
                    limit=40,
                ),
            )
    elif tool_name == "entity_lookup":
        safe["found"] = data.get("found") is True
        raw_entity = data.get("entity")
        if isinstance(raw_entity, Mapping):
            entity: dict[str, Any] = {}
            for key, limit in (
                ("id", 160),
                ("name", 240),
                ("entity_type", 80),
                ("description", 500),
            ):
                value = _graph_text_for_prompt(raw_entity.get(key), limit=limit)
                if value:
                    entity[key] = value
            safe["entity"] = entity
        else:
            safe["entity"] = None
        for key, limit in (
            ("as_of", 32),
            ("known_at", 40),
            ("known_at_floor", 40),
            ("identity_basis", 40),
            ("temporal_basis", 40),
        ):
            if key in data:
                safe[key] = _graph_text_for_prompt(data.get(key), limit=limit)
        if "history_complete" in data:
            safe["history_complete"] = data.get("history_complete") is True
        profile = data.get("profile")
        if isinstance(profile, Mapping):
            raw_tags = profile.get("tags")
            date_range = profile.get("document_date_range")
            safe_profile: dict[str, Any] = {
                "tags": [
                    _graph_text_for_prompt(tag, limit=80)
                    for tag in (raw_tags[:20] if isinstance(raw_tags, list) else [])
                    if isinstance(tag, str)
                ],
                "documents_without_own_date": _graph_count(profile.get("documents_without_own_date")),
            }
            if isinstance(date_range, Mapping):
                safe_profile["document_date_range"] = {
                    "earliest": _graph_text_for_prompt(date_range.get("earliest"), limit=32),
                    "latest": _graph_text_for_prompt(date_range.get("latest"), limit=32),
                }
            elif date_range is None:
                safe_profile["document_date_range"] = None
            safe["profile"] = safe_profile
        for key in ("knowledge_objects_total", "pending_relations_count"):
            if key in data:
                safe[key] = _graph_count(data.get(key))
        raw_provenance = data.get("profile_provenance")
        if isinstance(raw_provenance, Mapping):
            safe["profile_provenance"] = {
                "derived": raw_provenance.get("derived") is True,
                "derived_from": _graph_text_for_prompt(
                    raw_provenance.get("derived_from"),
                    limit=120,
                ),
                "source_count": _graph_count(raw_provenance.get("source_count")),
                "computed_at": _graph_text_for_prompt(
                    raw_provenance.get("computed_at"),
                    limit=40,
                ),
                "calculation": _graph_text_for_prompt(
                    raw_provenance.get("calculation"),
                    limit=100,
                ),
            }
        for key, fields in (
            ("event_time", ("occurred_at", "occurred_end", "precision")),
            ("edits", ("versions", "last_edited_at", "restorable_version")),
        ):
            raw_block = data.get(key)
            if isinstance(raw_block, Mapping):
                safe[key] = {
                    field: (
                        _graph_count(raw_block.get(field))
                        if field in {"versions", "restorable_version"}
                        else _graph_text_for_prompt(raw_block.get(field), limit=80)
                    )
                    for field in fields
                    if field in raw_block
                }
            elif raw_block is None and key in data:
                safe[key] = None
        raw_relations = data.get("relations")
        if isinstance(raw_relations, list):
            relations = [_safe_entity_relation(item) for item in raw_relations[:_SAFE_ENTITY_RELATIONS]]
            safe["relations"] = [item for item in relations if item]
            matched = _graph_count(
                data.get("relations_matched_at_least"),
                minimum=len(raw_relations),
            )
            safe["relations_matched_at_least"] = matched
            safe["relations_truncated"] = bool(data.get("relations_truncated")) or matched > len(
                safe["relations"]
            )
        raw_knowledge = data.get("knowledge_objects")
        knowledge = (
            [_safe_memory_result(item) for item in raw_knowledge[:_SAFE_ENTITY_KNOWLEDGE]]
            if isinstance(raw_knowledge, list)
            else []
        )
        safe["knowledge_objects"] = [item for item in knowledge if item]
        if isinstance(raw_knowledge, list) and len(raw_knowledge) > len(safe["knowledge_objects"]):
            safe["knowledge_objects_truncated"] = True
    else:
        return dict(data)

    # Keep JSON structurally valid. Remove complete tail objects; never rely on
    # ToolResult's character slice to bisect an envelope.
    while len(json.dumps(safe, ensure_ascii=False, indent=2)) > _SAFE_GRAPH_TOOL_PAYLOAD_MAX_CHARS:
        result_items = safe.get("results")
        knowledge_items = safe.get("knowledge_objects")
        relation_items = safe.get("relations")
        if isinstance(result_items, list) and result_items:
            result_items.pop()
            safe["results_shown"] = len(result_items)
            safe["results_truncated"] = True
        elif isinstance(knowledge_items, list) and knowledge_items:
            knowledge_items.pop()
            safe["knowledge_objects_truncated"] = True
        elif isinstance(relation_items, list) and relation_items:
            relation_items.pop()
            safe["relations_truncated"] = True
        else:
            raise ValueError(f"safe {tool_name} payload exceeds its structural budget")
    return safe


def _graph_tool_result_is_graph_bearing(tool_name: str, data: Any) -> bool:
    if not isinstance(data, Mapping):
        return False
    if tool_name == "memory_search":
        return isinstance(data.get("graph_context"), Mapping)
    if tool_name == "entity_lookup":
        return isinstance(data.get("graph_context"), Mapping) or isinstance(data.get("relations"), list)
    return False


def _temporal_boundary_from_graph_context(
    graph_context: Any,
) -> tuple[str, str, str, bool, str, str] | None:
    if not isinstance(graph_context, Mapping):
        return None
    if not (graph_context.get("as_of") or graph_context.get("known_at")):
        return None
    try:
        return _tool_temporal_contract(
            graph_context,
            requested_as_of="",
            requested_known_at="",
            label="initial graph context",
        )
    except ValueError:
        return None


def _graph_paths_for_prompt(
    graph_context: dict[str, Any],
    knowledge_labels: dict[str, str],
) -> list[dict[str, Any]]:
    """Render bounded ordered paths and bind their evidence to existing ``K`` labels.

    The graph snapshot is untrusted retrieval data.  In particular, relation
    ``metadata_json`` and free-form evidence text must not become a second route into
    the prompt.  A compact allowlist makes the temporal claim inspectable while the
    existing Knowledge Object envelope remains the only source of quotable evidence.
    """

    raw_paths = graph_context.get("paths")
    if not isinstance(raw_paths, list):
        return []
    entity_lookup: dict[str, dict[str, Any]] = {}
    for collection_name in ("nodes", "entities", "roots"):
        raw_entities = graph_context.get(collection_name)
        if not isinstance(raw_entities, list):
            continue
        for raw_entity in raw_entities:
            if not isinstance(raw_entity, dict):
                continue
            entity_id = _graph_endpoint_id_for_prompt(raw_entity.get("id"))
            if entity_id:
                entity_lookup.setdefault(entity_id, raw_entity)
    rendered: list[dict[str, Any]] = []
    for raw_path in raw_paths[:6]:
        if not isinstance(raw_path, dict):
            continue
        # Public snapshots keep a path-local endpoint legend because the global
        # node list has an independent cap.  Fold it into the same safe lookup
        # before rendering root/target and individual steps.
        raw_path_entities = raw_path.get("entities")
        if isinstance(raw_path_entities, list):
            for raw_entity in raw_path_entities[:5]:
                if not isinstance(raw_entity, dict):
                    continue
                entity_id = _graph_endpoint_id_for_prompt(raw_entity.get("id"))
                if entity_id:
                    entity_lookup.setdefault(entity_id, raw_entity)
        # ``edges`` is proposal 26's canonical snapshot contract.  ``steps`` is
        # accepted only for short-lived fakes written while the contract landed.
        raw_steps = raw_path.get("edges")
        if not isinstance(raw_steps, list):
            raw_steps = raw_path.get("steps")
        if not isinstance(raw_steps, list) or not raw_steps:
            continue
        steps: list[dict[str, Any]] = []
        anchors: list[bool] = []
        steps_complete = True
        for raw_step in raw_steps[:4]:
            if not isinstance(raw_step, dict):
                steps_complete = False
                continue
            step: dict[str, Any] = {}
            for key, limit in (
                ("id", 120),
                ("direction", 16),
                ("type", 80),
                ("valid_from", 32),
                ("valid_to", 32),
                ("created_at", 40),
                ("invalidated_at", 40),
                ("superseded_by", 120),
            ):
                value = raw_step.get(key)
                if isinstance(value, str):
                    step[key] = value[:limit]
            for key in ("from", "to", "source", "target"):
                if key in raw_step:
                    step[key] = _graph_endpoint_for_prompt(raw_step[key], entity_lookup)
            weight = _graph_number(raw_step.get("weight"))
            if weight is not None:
                step["weight"] = weight
            step["implicit"] = bool(raw_step.get("implicit"))

            raw_provenance = raw_step.get("provenance")
            provenance_source = raw_provenance if isinstance(raw_provenance, dict) else {}
            provenance: dict[str, Any] = {}
            origin = _graph_text_for_prompt(provenance_source.get("origin"), limit=80)
            source = _graph_text_for_prompt(provenance_source.get("source"), limit=80)
            candidate_id = _graph_text_for_prompt(provenance_source.get("candidate_id"), limit=120)
            reviewed = provenance_source.get("reviewed") is True
            trusted_review = (
                not bool(raw_step.get("implicit"))
                and origin == "review"
                and source == "reviewed_relation_candidate"
                and bool(candidate_id)
                and reviewed
            )
            trusted_implicit = (
                bool(raw_step.get("implicit"))
                and origin == "implicit_cooccurrence"
                and source == "accepted_knowledge_links"
            )
            trusted_anchor = trusted_review or trusted_implicit
            for key, limit in (("origin", 80),):
                value = provenance_source.get(key)
                if isinstance(value, str):
                    provenance[key] = value[:limit]
            if trusted_anchor:
                for key, limit in (
                    ("source", 80),
                    ("candidate_id", 120),
                    ("status", 40),
                    ("created_at", 40),
                    ("method", 80),
                    ("reviewed_at", 40),
                ):
                    value = provenance_source.get(key)
                    if isinstance(value, str):
                        provenance[key] = value[:limit]
                if trusted_review:
                    provenance["reviewed"] = True
                confidence = _graph_number(provenance_source.get("confidence"))
                if confidence is not None:
                    provenance["confidence"] = confidence
            knowledge_id = ""
            if trusted_anchor:
                knowledge_id = _graph_text_for_prompt(
                    provenance_source.get("knowledge_object_id") or raw_step.get("knowledge_object_id"),
                    limit=120,
                )
                if knowledge_id:
                    provenance["knowledge_object_id"] = knowledge_id
            citation = knowledge_labels.get(knowledge_id)
            if citation:
                provenance["citation"] = citation
            if provenance:
                step["provenance"] = provenance
            traversal_from = _graph_endpoint_id_for_prompt(raw_step.get("from"))
            traversal_to = _graph_endpoint_id_for_prompt(raw_step.get("to"))
            assertion_source = _graph_endpoint_id_for_prompt(raw_step.get("source"))
            assertion_target = _graph_endpoint_id_for_prompt(raw_step.get("target"))
            direction = _graph_text_for_prompt(raw_step.get("direction"), limit=16)
            expected_assertion = (
                (traversal_from, traversal_to) if direction == "forward" else (traversal_to, traversal_from)
            )
            coherent_step = (
                bool(_graph_text_for_prompt(raw_step.get("id"), limit=120))
                and bool(traversal_from)
                and bool(traversal_to)
                and direction in {"forward", "reverse"}
                and (assertion_source, assertion_target) == expected_assertion
            )
            anchors.append(bool(citation) and coherent_step)
            steps.append(step)
        if not steps:
            continue

        raw_entity_ids = raw_path.get("entity_ids")
        entity_ids = (
            [_graph_endpoint_id_for_prompt(item) for item in raw_entity_ids[:5]]
            if isinstance(raw_entity_ids, list)
            else []
        )
        path_id = _graph_text_for_prompt(raw_path.get("path_id") or raw_path.get("id"), limit=120)
        root_id = _graph_endpoint_id_for_prompt(raw_path.get("root"))
        target_id = _graph_endpoint_id_for_prompt(raw_path.get("target"))
        coherent_chain = (
            steps_complete
            and len(steps) == len(raw_steps)
            and len(entity_ids) == len(raw_steps) + 1
            and bool(path_id)
            and all(entity_ids)
            and len(set(entity_ids)) == len(entity_ids)
            and root_id == entity_ids[0]
            and target_id == entity_ids[-1]
            and all(
                isinstance(raw_step, dict)
                and _graph_endpoint_id_for_prompt(raw_step.get("from")) == entity_ids[index]
                and _graph_endpoint_id_for_prompt(raw_step.get("to")) == entity_ids[index + 1]
                for index, raw_step in enumerate(raw_steps)
            )
        )
        path: dict[str, Any] = {
            "path_id": path_id,
            "root": _graph_endpoint_for_prompt(raw_path.get("root"), entity_lookup),
            "target": _graph_endpoint_for_prompt(raw_path.get("target"), entity_lookup),
            "entity_ids": entity_ids,
            "steps": steps,
            # An incomplete path must never be promoted to grounded merely because
            # its first four edges happen to have anchors.
            "grounded": len(raw_steps) <= 4 and coherent_chain and bool(anchors) and all(anchors),
        }
        score = _graph_number(raw_path.get("score"))
        if score is not None:
            path["score"] = score
        if len(raw_steps) > 4:
            path["steps_truncated"] = True
        rendered.append(path)
    while rendered and len(json.dumps(rendered, ensure_ascii=False)) > _AGENT_GRAPH_PATHS_MAX_CHARS:
        rendered.pop()
    return rendered


# What an assistant turn's [K#] becomes when the record it named is not in this
# turn's retrieval at all. Losing the marker silently would be worse: the sentence
# would read as an unattributed claim.
_CITATION_OUT_OF_VIEW = "(источник вне текущей выборки)"


def _relabel_history_citations(
    content: str,
    history_item: dict[str, Any],
    current_labels: dict[str, str],
) -> str:
    """Rewrite an earlier turn's [K#] labels into this turn's numbering.

    Labels are assigned per turn, by position in that turn's retrieval — so [K2] in
    the answer three messages ago and [K2] in this turn's context are, in general,
    different Knowledge Objects. The old answers stayed in the prompt verbatim, and
    the model read them against the CURRENT legend: a claim the user had already been
    shown, now attributed to somebody else's note. Each message carries the map that
    was true when it was written, so the rewrite goes label → knowledge id → the label
    that id holds now.
    """
    if "[K" not in content and "[k" not in content:
        return content
    try:
        stored = json.loads(history_item.get("metadata_json") or "{}")
    except (TypeError, ValueError):
        stored = {}
    written_with = stored.get("knowledge_citations") if isinstance(stored, dict) else None
    if not isinstance(written_with, dict):
        written_with = {}

    def rewrite(match: re.Match[str]) -> str:
        label = match.group(1).upper()
        knowledge_id = written_with.get(label) or written_with.get(f"[{label}]")
        current = current_labels.get(str(knowledge_id)) if knowledge_id else None
        return f"[{current}]" if current else _CITATION_OUT_OF_VIEW

    return _KNOWLEDGE_CITATION_RE.sub(rewrite, content)


#: Настоящая ссылка имеет только форму `[K1]`…`[K99]` или
#: канонической группы. Сканер ниже сначала забирает весь
#: кандидат — включая пробел после `[`, табы, вложение и ошибочный
#: перенос строки, — и только потом решает, восстановимо ли его оставить.
_CANONICAL_CITATION_GROUP_BODY_RE = re.compile(r"K *[1-9][0-9]?(?: *[,;，；] *K *[1-9][0-9]?)*")
_CITATION_OPENERS = frozenset({"[", "［"})
_CITATION_CLOSERS = frozenset({"]", "］"})
_CITATION_SEPARATORS = frozenset({",", ";", "，", "；"})
_CITATION_MAX_LABELS = 32
_CITATION_UNKNOWN_K_CONFUSABLES = frozenset({"ĸ", "ᴋ", "ᛕ"})


def _is_citation_k(char: str) -> bool:
    """Match accepted K forms plus a closed set that must fail citation parsing."""

    normalized = unicodedata.normalize("NFKC", str(char or "")).casefold()
    return normalized in {"k", "κ", "к"} or str(char or "").casefold() in _CITATION_UNKNOWN_K_CONFUSABLES


def _is_accepted_citation_k(char: str) -> bool:
    """Whether a citation K can be bound to a canonical available label."""

    normalized = unicodedata.normalize("NFKC", str(char or "")).casefold()
    return normalized in {"k", "κ", "к"}


def _citation_line_breaks(value: str) -> int:
    return value.count("\n") + sum(
        1 for index, char in enumerate(value) if char == "\r" and value[index + 1 : index + 2] != "\n"
    )


def _citation_like_bracket_spans(text: str) -> list[tuple[int, int]]:
    """Locate whole numeric/fake citation candidates without touching prose brackets.

    The span finder owns the balanced *outer* bracket structure.  This is
    intentionally separate from validating a group: nested, cross-line,
    overlong and confusable forms are still one candidate and are removed as a
    unit instead of leaving a live-looking suffix behind.
    """

    def _citation_tail_end(position: int) -> int:
        probe = position
        while probe < len(text) and text[probe].isspace():
            probe += 1
        if probe < len(text) and text[probe] in _CITATION_CLOSERS:
            while probe < len(text) and text[probe] in _CITATION_CLOSERS:
                probe += 1
            return probe
        if probe >= len(text) or text[probe] not in _CITATION_SEPARATORS:
            return position
        atom = probe + 1
        while atom < len(text) and text[atom].isspace():
            atom += 1
        if atom >= len(text) or not _is_citation_k(text[atom]):
            return position
        end = probe
        while end < len(text):
            char = text[end]
            if (
                char.isspace()
                or char.isdecimal()
                or char in _CITATION_SEPARATORS | _CITATION_CLOSERS
                or _is_citation_k(char)
            ):
                end += 1
                continue
            break
        return end

    spans: list[tuple[int, int]] = []
    cursor = 0
    while cursor < len(text):
        start = next((index for index in range(cursor, len(text)) if text[index] in _CITATION_OPENERS), -1)
        if start == -1:
            break
        probe = start
        open_count = 0
        while probe < len(text):
            if text[probe] in _CITATION_OPENERS:
                open_count += 1
                probe += 1
                continue
            if text[probe].isspace():
                probe += 1
                continue
            break
        if not open_count or probe >= len(text) or not _is_citation_k(text[probe]):
            cursor = start + 1
            continue
        atom = probe + 1
        while atom < len(text) and text[atom].isspace():
            atom += 1
        numeric = atom < len(text) and text[atom].isdecimal()
        hyphen_numeric = bool(atom + 1 < len(text) and text[atom] == "-" and text[atom + 1].isdecimal())
        nested_atom = atom
        nested_k_candidate = False
        if nested_atom < len(text) and text[nested_atom] in _CITATION_OPENERS:
            while nested_atom < len(text) and (
                text[nested_atom].isspace()
                or text[nested_atom] in _CITATION_OPENERS
                or _is_citation_k(text[nested_atom])
            ):
                nested_atom += 1
            nested_k_candidate = nested_atom < len(text) and text[nested_atom].isdecimal()
        alias_match = re.match(
            r"(?:[_-]\s*(?:source|src|ref(?:erence)?|citation|источник)\b|"
            r"\s+(?:source|src|ref(?:erence)?|citation|источник)\b|"
            r"[Bb](?=\s*[\]］]))",
            text[probe + 1 :],
            re.I,
        )
        fake_alias = alias_match is not None
        if not numeric and not hyphen_numeric and not nested_k_candidate and not fake_alias:
            cursor = start + 1
            continue
        close: int | None = None
        last_close: int | None = None
        depth = 0
        for index in range(start, len(text)):
            char = text[index]
            if char in _CITATION_OPENERS:
                depth += 1
            elif char in _CITATION_CLOSERS:
                last_close = index
                if depth:
                    depth -= 1
                if depth == 0:
                    close = index
                    break
        if close is not None:
            end = close + 1
            while end < len(text) and text[end] in _CITATION_CLOSERS:
                end += 1
            end = max(end, _citation_tail_end(end))
        elif last_close is not None:
            end = max(last_close + 1, _citation_tail_end(last_close + 1))
        else:
            # Consume the entire citation-token prefix while preserving the
            # first ordinary word or punctuation after an unterminated group.
            # The remaining text cannot begin with a citation-shaped residue.
            end = probe + 1 + alias_match.end() if fake_alias and alias_match is not None else atom
            while end < len(text):
                char = text[end]
                if (
                    char.isspace()
                    or char.isdecimal()
                    or char in _CITATION_SEPARATORS | _CITATION_OPENERS | _CITATION_CLOSERS
                    or _is_citation_k(char)
                ):
                    end += 1
                    continue
                break
        raw = text[start:end]
        if re.fullmatch(r"(?:\[[Kk]-[0-9]+\]|［[Kk]-[0-9]+］)", raw):
            cursor = end
            continue
        spans.append((start, end))
        cursor = max(end, start + 1)
    return spans


def _ascii_k_body(value: str) -> str:
    normalized = unicodedata.normalize("NFKC", str(value or ""))
    return "".join("K" if _is_accepted_citation_k(char) else char for char in normalized)


def _strip_invented_citations(content: str, available: Any = None) -> str:
    """Убрать ссылки, которые модель придумала: открыть их всё равно нельзя.

    Замерено на недельном прогоне 2026-08-02: отвечая по веб-выдаче, модель
    ставила `[K_source]` — по образцу настоящих `[K1]`, но ни на что не
    указывающую. Человек видел в тексте служебный мусор, а «ссылка», которую
    невозможно открыть, ещё и врёт про обоснованность ответа.

    НОМЕРНЫЕ метки тоже бывают выдуманными, и это найдено на живом диалоге с
    новым человеком 2026-08-03: в ответе стояли `[K1]`, `[K2]`, `[K3]` при НУЛЕ
    найденных документов и нуле поданных источников. Прежняя редакция считала
    номерную метку настоящей по одному её виду и пропускала все три.

    Это хуже служебного мусора: `[K_source]` человек прочтёт как сбой, а `[K1]`
    выглядит как ссылка на его собственный документ — то есть ответ из головы
    подаётся как ответ по архиву.

    `available` — номера поданных источников (ключи `context.knowledge_citations`).
    Без него номерные метки не трогаются: молча вырезать законные ссылки, не зная
    списка, хуже, чем оставить лишнюю.
    """
    text = str(content or "")
    known: set[str] | None = None
    if available is not None:
        known = set()
        for label in available:
            parsed = re.fullmatch(
                r"\[?\s*K?\s*([1-9][0-9]?)\s*\]?",
                _ascii_k_body(str(label)),
                re.IGNORECASE,
            )
            if parsed is not None:
                known.add(str(int(parsed.group(1))))

    def _filter_numeric_group(raw: str) -> str:
        if not raw or raw[0] not in _CITATION_OPENERS or raw[-1] not in _CITATION_CLOSERS:
            return ""
        matching_pair = (raw[0], raw[-1]) in {("[", "]"), ("［", "］")}
        if not matching_pair:
            return ""
        if (
            sum(char in _CITATION_OPENERS for char in raw) != 1
            or sum(char in _CITATION_CLOSERS for char in raw) != 1
            or "\n" in raw
            or "\r" in raw
        ):
            return ""
        body = raw[1:-1].strip()
        if any(char in {"﹐", "﹔"} for char in body):
            return ""
        normalized_body = "".join(
            (" " if char.isspace() else "," if char == "，" else ";" if char == "；" else char)
            for char in _ascii_k_body(body)
        )
        if _CANONICAL_CITATION_GROUP_BODY_RE.fullmatch(normalized_body) is None:
            return ""
        raw_labels = re.split(r"[,;，；]", body)
        normalized_labels = re.split(r" *[,;] *", normalized_body)
        if len(raw_labels) != len(normalized_labels) or len(raw_labels) > _CITATION_MAX_LABELS:
            return ""
        kept: list[str] = []
        seen: set[str] = set()
        for label, normalized_label in zip(raw_labels, normalized_labels, strict=True):
            stripped = label.strip()
            parsed = re.fullmatch(
                r"K *(?P<number>[1-9][0-9]?)",
                normalized_label,
            )
            if parsed is None or not stripped:
                return ""
            number = str(int(parsed.group("number")))
            if number in seen or (known is not None and number not in known):
                continue
            seen.add(number)
            prefix = stripped[0] if stripped[0] in {"K", "k"} else "K"
            kept.append(f"{prefix}{number}")
        if not kept:
            return ""
        if (
            len(kept) == len(raw_labels)
            and ";" not in body
            and "，" not in body
            and "；" not in body
            and raw.startswith("[")
            and raw.endswith("]")
            and re.fullmatch(
                r"\[[Kk][1-9][0-9]?(?:[ \t]*,[ \t]*[Kk][1-9][0-9]?)*\]",
                raw,
            )
            is not None
            and not any(_is_citation_k(char) and char not in {"K", "k"} for char in raw)
        ):
            return raw
        return f"[{', '.join(kept)}]"

    def _rewrite_candidates(value: str) -> str:
        def _rstrip_horizontal(part: str) -> str:
            end = len(part)
            while end > 0 and part[end - 1].isspace() and part[end - 1] not in "\r\n":
                end -= 1
            return part[:end]

        def _last_visible_char(prefix: str, pieces: list[str]) -> str:
            if prefix:
                return prefix[-1]
            for piece in reversed(pieces):
                if piece:
                    return piece[-1]
            return ""

        def _is_lexical_seam(char: str) -> bool:
            return bool(char) and (char.isalnum() or char in {"_", "-"})

        pieces: list[str] = []
        cursor = 0
        for start, end in _citation_like_bracket_spans(value):
            prefix = value[cursor:start]
            replacement = _filter_numeric_group(value[start:end])
            cursor = end
            if not replacement:
                after_hspace = end
                while (
                    after_hspace < len(value)
                    and value[after_hspace].isspace()
                    and value[after_hspace] not in "\r\n"
                ):
                    after_hspace += 1
                next_char = value[after_hspace : after_hspace + 1]
                has_left = bool(prefix) or any(pieces)
                if next_char in {",", ".", ":", ";", "!", "?", "\n", "\r"} or not next_char:
                    prefix = _rstrip_horizontal(prefix)
                    cursor = after_hspace
                elif after_hspace > end and prefix and prefix[-1].isspace() and prefix[-1] not in "\r\n":
                    prefix = _rstrip_horizontal(prefix)
                elif after_hspace > end and not has_left:
                    cursor = after_hspace
                elif (
                    after_hspace == end
                    and next_char
                    and _is_lexical_seam(next_char)
                    and _is_lexical_seam(_last_visible_char(prefix, pieces))
                ):
                    prefix += " "
            pieces.append(prefix)
            pieces.append(replacement)
        pieces.append(value[cursor:])
        return "".join(pieces)

    cleaned = text
    # Every unsafe rewrite either removes bytes or replaces one candidate by a
    # canonical group.  Iterate to the fixed point so arbitrarily repeated
    # openers cannot expose a second live-looking layer after the first pass.
    for _ in range(len(text) + 1):
        rewritten = _rewrite_candidates(cleaned)
        if rewritten == cleaned:
            break
        cleaned = rewritten
    return cleaned


def _unknown_verdict(reason: str) -> dict[str, Any]:
    """Fail-closed verdict: a verifier that cannot vouch never reports success."""
    return {"status": VERDICT_UNKNOWN, "ok": False, "score": None, "issues": [reason]}


def _extract_json_object(text: str) -> dict[str, Any] | None:
    """Pull the first balanced JSON object out of a model reply.

    Models routinely wrap the requested JSON in prose or ```json fences, so a bare
    ``json.loads`` on the whole reply raises — and, historically, that exception was
    swallowed and treated as a pass. Scanning for a balanced object honours a
    well-formed verdict buried in noise while a genuinely unparseable reply still
    fails closed.
    """
    if not text:
        return None
    depth = 0
    start = -1
    in_string = False
    escape = False
    for index, char in enumerate(text):
        if in_string:
            if escape:
                escape = False
            elif char == "\\":
                escape = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
        elif char == "{":
            if depth == 0:
                start = index
            depth += 1
        elif char == "}" and depth > 0:
            depth -= 1
            if depth == 0 and start >= 0:
                try:
                    parsed = json.loads(text[start : index + 1])
                except (ValueError, json.JSONDecodeError):
                    start = -1
                    continue
                if isinstance(parsed, dict):
                    return parsed
                start = -1
    return None


def _normalize_verdict(
    content: str,
    *,
    require_request_satisfied: bool = False,
) -> dict[str, Any]:
    """Turn a raw judge reply into a trusted verdict, failing closed on any doubt."""
    parsed = _extract_json_object(content)
    if parsed is None:
        return _unknown_verdict("verdict not parseable")
    ok = parsed.get("ok")
    if not isinstance(ok, bool):
        # A verdict without an explicit boolean is not trustworthy.
        return _unknown_verdict("verdict missing boolean 'ok'")
    request_satisfied: bool | None = None
    if require_request_satisfied:
        raw_request_satisfied = parsed.get("request_satisfied")
        if not isinstance(raw_request_satisfied, bool):
            return _unknown_verdict("verdict missing boolean 'request_satisfied'")
        request_satisfied = raw_request_satisfied
        if not request_satisfied:
            ok = False
    score: float | None = None
    raw_score = parsed.get("score")
    if isinstance(raw_score, (int, float)) and not isinstance(raw_score, bool):
        score = max(0.0, min(1.0, float(raw_score)))
    issues: list[str] = []
    raw_issues = parsed.get("issues")
    if isinstance(raw_issues, list):
        issues = [str(item).strip() for item in raw_issues if str(item).strip()][:10]
    if require_request_satisfied and request_satisfied is False:
        issues = ["attachment_request_not_answered", *issues]
        issues = list(dict.fromkeys(issues))[:10]
    return {
        "status": VERDICT_PASSED if ok else VERDICT_FAILED,
        "ok": ok,
        "score": score,
        "issues": issues,
        **(
            {"request_satisfied": request_satisfied}
            if require_request_satisfied and request_satisfied is not None
            else {}
        ),
    }


#: Сколько знаков отдаётся под перечень замечаний автопроверки и сколько — под
#: одно замечание. Пределы есть (предупреждение не должно вытеснить сам ответ),
#: но теперь они РЕЖУТ ПО ЦЕЛЫМ замечаниям и говорят, сколько осталось за кадром.
_CAUTION_DETAIL_LIMIT = 600
_CAUTION_ITEM_LIMIT = 200


def _verification_caution(status: str, issues: list[Any], *, from_the_web: bool = False) -> str:
    """User-facing warning for a failed or unverifiable answer (empty otherwise)."""
    if status == VERDICT_FAILED:
        head = (
            "⚠️ Часть сказанного не подтвердилась найденными источниками — перепроверьте факты."
            if from_the_web
            else "⚠️ Автопроверка нашла возможные несоответствия с вашими данными — перепроверьте факты."
        )
        # Замечания перечисляются ЦЕЛИКОМ, по одному в строке, и обрыв виден.
        #
        # Найдено владельцем 2026-08-02: «сообщения обрезаются в последнем блоке,
        # где автопроверка нашла возможные несоответствия». Прежняя редакция
        # склеивала замечания через «; » и рубила строку на двухсотом знаке —
        # посреди слова, без единого признака, что дальше было ещё. Человек
        # читал оборванную претензию к собственным данным и не мог узнать, в чём
        # она состояла.
        fixed_issue_labels = {
            "attachment_evidence_mismatch": (
                "Ответ может расходиться с содержимым вложения или перечислять его не полностью."
            ),
            "attachment_verification_unavailable": (
                "Содержимое вложения не удалось проверить автоматически."
            ),
            "attachment_verification_note": "Проверка вложения вернула служебное замечание.",
            "attachment_request_not_answered": (
                "Ответ опирается на вложение, но не отвечает на заданный вопрос."
            ),
        }
        clean = [
            fixed_issue_labels.get(str(item).strip(), str(item).strip())
            for item in issues
            if str(item).strip()
        ]
        if not clean:
            return head
        shown: list[str] = []
        budget = _CAUTION_DETAIL_LIMIT
        for item in clean:
            piece = item if len(item) <= _CAUTION_ITEM_LIMIT else item[: _CAUTION_ITEM_LIMIT - 1] + "…"
            if shown and len(piece) > budget:
                break
            shown.append(piece)
            budget -= len(piece)
        lines = "\n".join(f"• {piece}" for piece in shown)
        hidden = len(clean) - len(shown)
        tail = f"\n…и ещё {hidden} — целиком в админке." if hidden > 0 else ""
        return f"{head}\n{lines}{tail}"
    if status == VERDICT_UNKNOWN:
        if not from_the_web and "attachment_coverage_incomplete" in {str(item).strip() for item in issues}:
            return (
                "⚠️ Вложение удалось прочитать только в доступной части; полный состав "
                "документа не доказан. Итог ответа может быть неполным."
            )
        # Internal reasons (e.g. "verifier unavailable") are diagnostic, not shown.
        return (
            "⚠️ Не удалось автоматически проверить этот ответ по найденным веб-источникам — "
            "отнеситесь к нему осторожно."
            if from_the_web
            else "⚠️ Не удалось автоматически проверить этот ответ по вашим данным — "
            "отнеситесь к нему осторожно."
        )
    return ""


#: Ответ ОБЪЯВЛЯЕТ себя взятым из личного архива: «по базе знаний», «согласно
#: вашим документам», «опираясь на ваши записи».
#:
#: Проверяется вместе с фактом, который система знает точно: ссылок `[K#]` в
#: ответе ноль, то есть из архива в него не пришло НИЧЕГО. Утверждение о
#: происхождении при нулевых основаниях ложно, и это устанавливается без судьи.
#:
#: Ловится именно ПРОИСХОЖДЕНИЕ, а не упоминание архива: «в базе знаний нет
#: данных» — честная фраза и под правило не попадает, потому что предлога
#: «по/согласно/из/на основании» там нет. Слово «данные» из перечня убрано
#: намеренно: «по данным Росстата» — законная ссылка на внешний источник.
_CLAIMS_THE_ARCHIVE = re.compile(
    r"(?:по|согласно|из|на\s+основании|исходя\s+из|опира\w+\s+на|судя\s+по)\s+"
    r"(?:"
    r"(?:личн\w+\s+|ваш\w+\s+|тво\w+\s+|мо\w+\s+)?баз\w+(?:\s+знан\w+)?|"
    r"(?:ваш\w+\s+|тво\w+\s+|мо\w+\s+|личн\w+\s+)?архив\w*|"
    r"(?:ваш\w+|тво\w+|мо\w+|личн\w+|имеющ\w+ся)\s+(?:документ\w+|записе?\w+|запис\w+|материал\w+)"
    r")",
    re.IGNORECASE,
)

_PROVENANCE_TOKEN_RE = re.compile(r"[A-Za-zА-Яа-яЁё]+(?:-[A-Za-zА-Яа-яЁё]+)*")
_RU_ADJECTIVE_ENDINGS = frozenset({"ая", "ого", "ое", "ой", "ому", "ую", "ые", "ый", "ым", "ыми", "ых"})
_RU_SOFT_ADJECTIVE_ENDINGS = frozenset({"ая", "ие", "ий", "им", "ими", "их", "ого", "ое", "ой", "ому", "ую"})


def _ru_full_adjective_forms(*stems: str) -> frozenset[str]:
    """Expand only the finite regular adjective paradigm used by role tokens."""

    return frozenset(stem + ending for stem in stems for ending in _RU_ADJECTIVE_ENDINGS)


